// Demonstrating encapsulation as a data structure transformation.
// Each 'layer function' treats the layer above's output as an opaque payload.

function applicationLayer(message) {
  // HTTP GET request (simplified)
  return {
    method: 'GET',
    path: '/index.html',
    headers: { Host: 'example.com', 'Content-Type': 'text/plain' },
    body: message
  };
}

function transportLayer(appData, srcPort, dstPort) {
  // TCP segment: adds port numbers and sequence tracking
  return {
    srcPort,
    dstPort,
    sequenceNumber: Math.floor(Math.random() * 4294967295),
    ackNumber: 0,
    flags: { SYN: false, ACK: true, FIN: false },
    windowSize: 65535,
    payload: appData   // opaque — TCP doesn't know this is HTTP
  };
}

function networkLayer(tcpSegment, srcIP, dstIP) {
  // IP packet: adds addressing and routing metadata
  return {
    version: 4,
    ttl: 64,
    protocol: 6,       // 6 = TCP
    srcIP,
    dstIP,
    headerChecksum: 0xABCD,  // simplified
    payload: tcpSegment  // opaque — IP doesn't know this is TCP
  };
}

function dataLinkLayer(ipPacket, srcMAC, dstMAC) {
  // Ethernet frame: adds MAC addresses and CRC
  const payloadStr = JSON.stringify(ipPacket);
  // Simple XOR checksum (real CRC-32 is more complex)
  const crc = payloadStr.split('').reduce((acc, c) => (acc ^ c.charCodeAt(0)) >>> 0, 0);
  return {
    dstMAC,
    srcMAC,
    etherType: 0x0800,  // IPv4
    payload: ipPacket,  // opaque — Ethernet doesn't know this is IP
    crc
  };
}

// Sender: data travels DOWN the stack
const httpData = applicationLayer('Hello, World!');
const tcpSeg  = transportLayer(httpData, 54321, 443);
const ipPkt   = networkLayer(tcpSeg, '192.168.1.5', '93.184.216.34');
const ethFrm  = dataLinkLayer(ipPkt, 'AA:BB:CC:DD:EE:FF', '11:22:33:44:55:66');

console.log('--- Encapsulated Frame ---');
console.log('Ethernet dst MAC:', ethFrm.dstMAC);
console.log('IP dst address:  ', ethFrm.payload.dstIP);
console.log('TCP dst port:    ', ethFrm.payload.payload.dstPort);
console.log('HTTP path:       ', ethFrm.payload.payload.payload.path);
console.log('CRC checksum:    ', ethFrm.crc.toString(16));

// Receiver: data travels UP the stack (decapsulation)
function decapsulate(frame) {
  // Data Link: check CRC (simplified — just trust it), strip Ethernet header
  const ipPacket = frame.payload;
  // Network: check TTL, verify destination IP, strip IP header
  const tcpSegment = ipPacket.payload;
  // Transport: verify checksum, reassemble, deliver to port
  const appData = tcpSegment.payload;
  // Application: parse HTTP
  return appData;
}

const received = decapsulate(ethFrm);
console.log('\n--- Decapsulated at receiver ---');
console.log('HTTP method:', received.method);
console.log('HTTP path:  ', received.path);
console.log('Body:       ', received.body);

// Node.js low-level TCP server — illustrating socket concepts
// (Node's 'net' module exposes raw TCP sockets)

const net = require('net');

// Each accepted connection is a unique socket (src IP, src port, dst IP, dst port)
const server = net.createServer((socket) => {
  const remoteAddr = `${socket.remoteAddress}:${socket.remotePort}`;
  const localAddr  = `${socket.localAddress}:${socket.localPort}`;
  console.log(`Connection: ${remoteAddr} -> ${localAddr}`);
  // socket.remotePort is an ephemeral port assigned by the client's OS

  socket.on('data', (data) => {
    console.log(`Received ${data.length} bytes:`, data.toString().slice(0, 80));
    // Echo back — demonstrates full-duplex TCP
    socket.write(`Echo: ${data}`);
  });

  socket.on('end', () => {
    console.log(`FIN received from ${remoteAddr} — half-close`);
    socket.end(); // send our own FIN
  });

  socket.on('error', (err) => {
    console.error(`Socket error from ${remoteAddr}:`, err.message);
  });
});

// Bind to port 8080 on all interfaces
server.listen(8080, '0.0.0.0', () => {
  const addr = server.address();
  console.log(`Listening on ${addr.address}:${addr.port}`);
  console.log('Well-known port comparison: HTTP=80, HTTPS=443, SSH=22');
});

// Demonstrate ephemeral port assignment (client side)
const client = net.connect({ port: 8080, host: '127.0.0.1' }, () => {
  console.log(`Client ephemeral port: ${client.localPort}`);
  // OS assigns ephemeral port (typically 49152-65535)
  client.write('Hello from client!');
  client.end();
});

// OSI layer reference and encapsulation overhead calculator

// ── Layer Reference Table ─────────────────────────────────────
const OSI_LAYERS = [
  { num: 7, name: 'Application',  pdu: 'Data/Message', protocols: 'HTTP, DNS, SMTP, FTP, SSH', device: 'Firewall L7, Proxy' },
  { num: 6, name: 'Presentation', pdu: 'Data',          protocols: 'TLS/SSL, gzip, JPEG',       device: '—' },
  { num: 5, name: 'Session',      pdu: 'Data',          protocols: 'RPC, NetBIOS',               device: '—' },
  { num: 4, name: 'Transport',    pdu: 'Segment',       protocols: 'TCP, UDP, QUIC',             device: 'Load balancer L4' },
  { num: 3, name: 'Network',      pdu: 'Packet',        protocols: 'IP, ICMP, BGP, OSPF',        device: 'Router' },
  { num: 2, name: 'Data Link',    pdu: 'Frame',         protocols: 'Ethernet, 802.11 (Wi-Fi)',   device: 'Switch' },
  { num: 1, name: 'Physical',     pdu: 'Bit',           protocols: 'Cat6, Fibre, 5G, USB',      device: 'Hub, NIC, Cable' },
];

console.log('OSI Layer | PDU     | Key Protocols');
OSI_LAYERS.forEach(l => {
  console.log(`Layer ${l.num} ${l.name.padEnd(12)} | ${l.pdu.padEnd(7)} | ${l.protocols}`);
});

// ── Encapsulation Overhead Calculator ────────────────────────
const ETHERNET_HDR = 14;  // bytes: dst MAC(6) + src MAC(6) + EtherType(2)
const ETHERNET_FCS = 4;   // CRC-32 trailer
const IP_HDR_MIN   = 20;  // bytes (no options)
const TCP_HDR_MIN  = 20;  // bytes (no options)
const UDP_HDR      = 8;   // bytes: fixed size always
const TLS_OVERHEAD = 29;  // ~5 byte header + 16 byte MAC + ~8 byte IV (AES-GCM)

function calculateTCPPayloadEfficiency(applicationPayloadBytes) {
  const totalOverhead = ETHERNET_HDR + ETHERNET_FCS + IP_HDR_MIN + TCP_HDR_MIN + TLS_OVERHEAD;
  const totalFrame = applicationPayloadBytes + totalOverhead;
  const efficiency = (applicationPayloadBytes / totalFrame * 100).toFixed(1);
  return { applicationPayloadBytes, totalOverhead, totalFrame, efficiency: `${efficiency}%` };
}

console.log('\nTCP/IP encapsulation overhead:');
console.log(calculateTCPPayloadEfficiency(1));    // 1-byte payload: very inefficient
console.log(calculateTCPPayloadEfficiency(100));  // Small HTTP request
console.log(calculateTCPPayloadEfficiency(1400)); // Near-MTU packet
console.log(calculateTCPPayloadEfficiency(8192)); // Larger payload (multiple frames)

// Mnemonic helpers
const MNEMONIC_BOTTOM_UP = 'Please Do Not Throw Sausage Pizza Away';
const MNEMONIC_TOP_DOWN  = 'All People Seem To Need Data Processing';
console.log('\nBottom→Top (L1→L7):', MNEMONIC_BOTTOM_UP);
console.log('Top→Bottom (L7→L1):', MNEMONIC_TOP_DOWN);
